const express = require('express');
const { ChromaClient } = require('chromadb');
const db = require('../db');

const chroma = new ChromaClient();
const app = express();
app.use(express.json());

app.post('/api/procurement/contracts/search', async (req, res) => {
  const { vendorId, queryText } = req.body;

  if (!vendorId || !queryText) {
    return res.status(400).json({ error: 'vendorId and queryText required' });
  }

  // Validate user has permission to manage or view the specified vendor
  const hasAccess = await db('vendor_access_grants')
    .where({ user_id: req.user.id, vendor_id: vendorId })
    .first();

  if (!hasAccess && req.user.role !== 'procurement_admin') {
    return res.status(403).json({ error: 'Unauthorized to search contracts for this vendor' });
  }

  try {
    const collection = await chroma.getCollection({ name: `vendor_contracts_${vendorId}` });
    const results = await collection.query({
      queryTexts: [queryText],
      nResults: 3
    });

    return res.json({
      vendorId,
      excerpts: results.documents[0],
      metadatas: results.metadatas[0]
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

module.exports = app;
